from __future__ import annotations

from typing import Any

from .base import ProviderTask
from .workers import IsolatedWorkerProvider
from .mineru_capture import CAPTURE_CODE


WORKER_CODE = CAPTURE_CODE + '\nimport contextlib\nimport importlib.metadata as md\nimport inspect\nimport json\nimport os\nimport shutil\nimport sys\nimport time\nimport traceback\nfrom pathlib import Path\n\nprotocol_out = sys.stdout\n\ndef emit(payload):\n    protocol_out.write(json.dumps(payload, ensure_ascii=False) + "\\n")\n    protocol_out.flush()\n\ndef package_version(name):\n    try:\n        return md.version(name)\n    except Exception as e:\n        return f"unavailable:{type(e).__name__}:{e}"\n\ndef find_best_markdown(root, stem):\n    root = Path(root)\n    candidates = [p for p in root.rglob("*.md") if p.is_file()]\n    exact = [p for p in candidates if p.name == f"{stem}.md"]\n    pool = exact or candidates\n    if not pool:\n        return None\n    return max(pool, key=lambda p: p.stat().st_size if p.exists() else -1)\n\ndef collect_refs(root, md_path):\n    root = Path(root)\n    refs = []\n    if md_path is not None and Path(md_path).exists():\n        refs.append(str(Path(md_path)))\n    suffix_order = ("_content_list_v2.json", "_content_list.json", "_middle.json")\n    for suffix in suffix_order:\n        matches = sorted(p for p in root.rglob(f"*{suffix}") if p.is_file())\n        if matches:\n            refs.append(str(matches[0]))\n    return refs\n\ntry:\n    with contextlib.redirect_stdout(sys.stderr):\n        import torch\n        import torchvision\n        from mineru.cli.common import do_parse, read_fn\n        from mineru.backend.pipeline.pipeline_analyze import doc_analyze_streaming\n    emit({\n        "status": "READY",\n        "provider_kind": "mineru_worker",\n        "package": "mineru",\n        "package_version": package_version("mineru"),\n        "sys_executable": sys.executable,\n        "sys_prefix": sys.prefix,\n    })\nexcept Exception as e:\n    emit({\n        "status": "INIT_FAILED",\n        "error": f"{type(e).__name__}: {e}",\n        "traceback": traceback.format_exc(),\n    })\n    raise\n\nfor raw_line in sys.stdin:\n    raw_line = raw_line.strip()\n    if not raw_line:\n        continue\n    try:\n        cmd = json.loads(raw_line)\n        op = str(cmd.get("op") or "")\n        if op == "ping":\n            emit({\n                "status": "PONG",\n                "nonce": cmd.get("nonce"),\n                "sys_executable": sys.executable,\n                "sys_prefix": sys.prefix,\n            })\n            continue\n        if op == "close":\n            emit({"status": "BYE"})\n            break\n        if op != "parse":\n            emit({"status": "BAD_COMMAND", "op": op})\n            continue\n\n        started = time.perf_counter()\n        input_path = Path(str(cmd["input"]))\n        raw_output_dir = Path(str(cmd["output_dir"]))\n        output_root = raw_output_dir / "mineru_output"\n        if output_root.exists():\n            shutil.rmtree(output_root)\n        output_root.mkdir(parents=True, exist_ok=True)\n\n        backend = str(cmd.get("backend") or "pipeline")\n        parse_method = str(cmd.get("parse_method") or "ocr")\n        lang = str(cmd.get("lang") or "ch")\n        formula_enable = bool(cmd.get("formula_enable", True))\n        table_enable = bool(cmd.get("table_enable", True))\n        stem = input_path.stem\n\n        # Keep stdout exclusively for the JSONL protocol. MinerU/tqdm/logging output is redirected to stderr.\n        with contextlib.redirect_stdout(sys.stderr):\n            from mineru.cli.common import do_parse, read_fn\n\n            pdf_bytes = read_fn(input_path)\n            kwargs = {\n                "output_dir": str(output_root),\n                "pdf_file_names": [stem],\n                "pdf_bytes_list": [pdf_bytes],\n                "p_lang_list": [lang],\n                "backend": backend,\n                "parse_method": parse_method,\n                "formula_enable": formula_enable,\n                "table_enable": table_enable,\n                "f_draw_layout_bbox": False,\n                "f_draw_span_bbox": False,\n                "f_dump_md": True,\n                "f_dump_middle_json": True,\n                "f_dump_model_output": False,\n                "f_dump_orig_pdf": False,\n                "f_dump_content_list": True,\n            }\n            sig = inspect.signature(do_parse)\n            accepts_varkw = any(p.kind == inspect.Parameter.VAR_KEYWORD for p in sig.parameters.values())\n            if not accepts_varkw:\n                kwargs = {k: v for k, v in kwargs.items() if k in sig.parameters}\n            import mineru.cli.common as mineru_common\n            with capture_supplemental(mineru_common, cmd.get("physical_page"), cmd.get("task_id")) as supplemental_evidence:\n                do_parse(**kwargs)\n\n        md_path = find_best_markdown(output_root, stem)\n        if md_path is None:\n            files = [str(p.relative_to(output_root)) for p in output_root.rglob("*") if p.is_file()]\n            raise FileNotFoundError(\n                "MinerU 未生成 Markdown；output files=" + json.dumps(files[:80], ensure_ascii=False)\n            )\n        refs = collect_refs(output_root, md_path)\n        text = md_path.read_text(encoding="utf-8", errors="replace")\n        emit({\n            "status": "SUCCESS",\n            "markdown_path": str(md_path),\n            "raw_refs": refs,\n            "elapsed_seconds": time.perf_counter() - started,\n            "backend": backend,\n            "parse_method": parse_method,\n            "lang": lang,\n            "formula_enable": formula_enable,\n            "table_enable": table_enable,\n            "char_count": len(text),\n            "supplemental_evidence": supplemental_evidence,\n        })\n    except Exception as e:\n        emit({\n            "status": "FAILED",\n            "error": f"{type(e).__name__}: {e}",\n            "traceback": traceback.format_exc(),\n        })\n'


class MinerUProvider(IsolatedWorkerProvider):
    default_python = ".venv-mineru/bin/python"
    result_path_key = "markdown_path"
    worker_code = WORKER_CODE
    dependency_probe_code = "import torch; import torchvision; from mineru.cli.common import do_parse, read_fn; from mineru.backend.pipeline.pipeline_analyze import doc_analyze_streaming; print('mineru=ok')"

    def build_command(self, task: ProviderTask) -> dict[str, Any]:
        command = super().build_command(task)
        command.update(
            {
                "physical_page": task.metadata.get("page_number") if task.metadata.get("task_type") == "PAGE_FALLBACK" else None,
                "task_id": task.task_id,
                "backend": str(self.config.get("backend") or "pipeline"),
                "parse_method": str(self.config.get("parse_method") or "ocr"),
                "lang": str(self.config.get("lang") or "ch"),
                "formula_enable": bool(self.config.get("formula_enable", True)),
                "table_enable": bool(self.config.get("table_enable", True)),
            }
        )
        return command

